// Phase 1: editable EC4 worksheet; uses existing engine operators only.
// No new solver or engine behaviour. See docs/composite-design/TECHNICAL.md.
import { createLayout, R } from './layout.mjs';
import { compositeFigures } from './compositeFigures.mjs';
const l = createLayout({ idPrefix: 's_ec4', sizesFile: 'sizes_composite.json', textFont: 'Roboto', mathColumn: 396 });
const { H, T, M, FU, fr, fo, LINK, S, finish } = l;
// Full-width internal-force graph on a white background (diagram style, not the house chart style).
const DIAGRAM = (h, props) => {
  const rows = (h + 16) / 40;
  l.need(rows);
  l.out.push({ id: l.id(), type: 'graph', x: 80, y: l.ln(l.st.page, l.st.row) - 8, props: { w: 630, h, xLabel: '', yLabel: '', grid: false, axesAtOrigin: true, font: 'Roboto', background: '#ffffff', equalAxes: false, ...props } });
  l.gap(rows);
};
// A description and its region print as one block, so a page break never separates them.
const P = (...args) => {
  const n = l.out.length;
  l.P(...args);
  for (const s of l.out.slice(n)) s.printGroupId = `s_ec4_pg_${n.toString(36)}`;
};
// Static symbolic figures; every value is in the worksheet regions.
const fig = compositeFigures(l);
const IF = (...branches) => {
  const rows = branches.map(([c, v], i) => (c === null ? R`\mathrm{else}` : `${i ? R`\mathrm{else}\ ` : ''}\\mathrm{if}\\ ${c}`) + R`\\\quad\left\Vert\displaystyle ${v}\right.`);
  return R`\begin{array}{||l}` + rows.join(R`\\`) + R`\end{array}`;
};
const units = u => ({ displayUnit: u, precision: 3 });
const input = (label, name, value, unit = '') => P(label, R`${name}\coloneq ${value}${unit ? R`\,\mathrm{${unit}}` : ''}`, M(units(unit)));
// full: true = full substitution, false = formula = result, 'fo' = formula only (long vectors; still calculated)
const calc = (label, name, rhs, unit = '', full = true) => P(label, R`${name}\coloneq ${rhs}`, M(units(unit), full === 'fo' ? fo : full ? FU : fr));
const check = (label, lhs, rhs) => P(label, R`${lhs}\le ${rhs}`, M({ precision: 3 }));
const ur = (label, name, demand, resistance) => {
  calc(label, R`\mathrm{UR}_{${name}}`, R`\frac{${demand}}{${resistance}}`);
  check('Acceptance', R`\mathrm{UR}_{${name}}`, '1');
};
H(1, 'COMPOSITE BEAM CALCULATION (EC4)');
T('REVIEW DRAFT. Singapore NA verification is outstanding. SS EN 1994-1-1 / EN 1994-1-1:2004.');
T('Simply supported, solid slab or composite slab on profiled steel deck (1.11), symmetric rolled I-section, ductile studs, sagging, no axial force.');
H(2, '1. INPUTS');
H(3, '1.1 Geometry');
input('Span', 'L', 8, 'm');
input('Beam spacing (load width)', 's_b', 3, 'm');
input('Slab thickness, overall (deck depth included)', 'h_c', 150, 'mm');
input('Stud-row separation (single row)', 'b_0', 0, 'mm');
H(3, '1.2 Materials');
input('Steel yield strength, t_f < 16 mm', 'f_y', 355, 'MPa');
input('Steel elastic modulus', 'E_a', 210, 'GPa');
input('Steel shear modulus', 'G_a', 81, 'GPa');
input('Concrete C30/37, EC2 Table 3.1', 'f_{ck}', 30, 'MPa');
input('Concrete secant modulus', 'E_{cm}', 33, 'GPa');
input('Wet RC density', '\\rho_c', 25, 'kN/m^3');
input('Reinforcement B500', 'f_{sk}', 500, 'MPa');
H(3, '1.3 Partial and combination factors (EN recommended; NA to confirm)');
for (const [sym,val,lab] of [['\\gamma_C',1.5,'Concrete'],['\\gamma_S',1.15,'Reinforcement'],['\\gamma_V',1.25,'Shear connectors'],['\\gamma_{M0}',1,'Steel, cross-section'],['\\gamma_{M1}',1,'Steel, member buckling'],['\\gamma_G',1.35,'Permanent actions'],['\\gamma_Q',1.5,'Variable actions'],['\\psi_2',0.3,'Quasi-permanent, imposed']]) input(lab,sym,val);
H(3, '1.4 Steel section (Browse the section library)');
P('Steel section (Browse to change)', R`\mathrm{Section}\coloneq3148`);
T('Library: BS 4-1 dimensions, properties from the geometry. Check against project tables.');
// t_f, t_w, r, I_z, I_t, I_w use the steel library's own definitions so Browse leaves them unchanged.
const SP = (name, i) => R`${name}\coloneq\operatorname{sectionProp}(\mathrm{Section},${i})`;
const props = [['h_a',0,'mm',1],['b_a',1,'mm',1],['t_f',3,'mm',1],['t_w',2,'mm',1],['r',4,'mm',1],['A_a',5,'cm^2',2],['I_a',6,'cm^4',0],['I_z',7,'cm^4',0],
  ['W_{pl}',10,'cm^3',0],['I_t',12,'cm^4',2],['I_w',13,'cm^6',0],['m_a',16,'kg/m',2]];
for (let i = 0; i < props.length; i += 3)
  l.ROW(props.slice(i, i + 3).map(([n, k, u, p], j) => [[96, 316, 516][j], SP(n, k), { displayMode: 'result', displayUnit: u, precision: p }]), 0.75);
H(3, '1.5 Construction stage');
input('Propping: 0 = unpropped (default), 1 = propped', 'c_{prop}', 0);
input('If propped: L_LT = k_LT L (prop spacing / span)', 'k_{LT}', 0.5);
input('Construction imposed load', 'q_{con}', 0.75, 'kPa');
input('Formwork load (removable)', 'g_{form}', 0.5, 'kPa');
H(3, '1.6 Load tables: one row per load; pattern G = permanent, Q = imposed');
const TBL = (x, cols, rows, widths) => ({ id: l.id(), type: 'table', x, y: l.ln(l.st.page, l.st.row) - 8, props: {
  w: widths.reduce((a, b) => a + b, 0), h: (rows.length + 2) * 32, rows: rows.length + 2, columns: cols.length, columnWidths: widths, headerRow: true, input: true,
  cells: [cols.map(([n]) => ({ value: n })), cols.map(([, u]) => ({ value: u })), ...rows.map(r => r.map(v => ({ value: v === '' ? '' : String(v) })))] } });
l.need(5);
l.textAt(l.st.page, l.st.row, 'Area loads (pressure × s_b), from x_1 to x_2', { size: 13, w: 340 });
l.textAt(l.st.page, l.st.row, 'Point loads at a', { size: 13, x: 438, w: 276 });
l.gap(0.5);
l.need(3.5);
l.out.push(TBL(76, [['Case c_Q.i', 'G/Q'], ['x_1.i', 'm'], ['x_2.i', 'm'], ['p_k.i', 'kPa'], ['ULS \\gamma_F.i', '']], [['G', 0, 8, 1.5, 1.35], ['Q', 0, 8, 3, 1.5]], [96, 46, 46, 52, 88]));
l.out.push(TBL(438, [['Case c_Q.j', 'G/Q'], ['a_j', 'm'], ['F_k.j', 'kN'], ['ULS \\gamma_F.j', '']], [['G', 3, 30, 1.35], ['Q', 3, 45, 1.5]], [90, 42, 54, 88]));
l.gap(3.5);
T('Area loads p_k in kPa: the line load p_k s_b and its ULS value γ_F p_k s_b are calculated (annex A.1).');
T('Case G/Q sets the SLS combination; γ_F is the ULS factor of the row (default 1.35 G, 1.5 Q).');
T('Self-weight g_0 (steel + wet slab) is added automatically with the fixed ULS factor γ_G.sw = 1.35.');
H(3, '1.7 Shear connection');
input('Stud diameter', 'd_{sc}', 19, 'mm');
input('Stud height after welding', 'h_{sc}', 100, 'mm');
input('Stud ultimate strength', 'f_u', 450, 'MPa');
input('Stud spacing, support A to max moment', 's_{sc.A}', 125, 'mm');
input('Stud spacing, max moment to support B', 's_{sc.B}', 200, 'mm');
H(3, '1.8 Slab transverse reinforcement (longitudinal shear, EC4 §6.6.6)');
input('Top transverse bar diameter (A_t)', 'd_{s.t}', 10, 'mm');
input('Top transverse bar spacing', 's_{f.t}', 150, 'mm');
input('Bottom transverse bar diameter (A_b)', 'd_{s.b}', 10, 'mm');
input('Bottom transverse bar spacing', 's_{f.b}', 150, 'mm');
input('Stud head diameter', 'd_{head}', 32, 'mm');
H(3, '1.9 Point loads and supports on the web (EN 1993-1-5 §6)');
input('Point loads on top flange (1) or framed in (0)', 'c_{F.P}', 1);
input('Stiff bearing length under a point load', 's_{s.P}', 100, 'mm');
input('Beam bears on supports (1) or end connection (0)', 'c_{F.S}', 1);
input('Stiff bearing length at a support', 's_{s.S}', 100, 'mm');
H(3, '1.10 Serviceability');
input('Creep coefficient', '\\varphi', 2);
input('Free shrinkage strain', '\\varepsilon_{cs}', 0.0003);
input('Deflection limit L / r_lim, total less precamber', 'r_{lim}', 250);
input('Deflection limit L / r_lim.1, construction stage', 'r_{lim.1}', 250);
input('Deflection limit L / r_lim.q, live load alone', 'r_{lim.q}', 360);
input('Precamber w_c, % of the self-weight (g_0) deflection; 0 = none', 'c_{cam}', 0);
input('Precamber, fixed value at mid-span, added to the % share; 0 = none', 'w_{c.0}', 0, 'mm');
input('Natural frequency limit (project; office floors 3 to 5 Hz)', 'f_{lim}', 4, 'Hz');
input('Share of the imposed load in the vibration mass', '\\psi_{vib}', 0.1);
input('Dynamic modulus of the concrete (38 GPa: SCI P354 / AD 433, normal weight; see 4.10)', 'E_{c.dyn}', 38, 'GPa');
H(3, '1.11 Slab type and profiled steel deck (EN 1994-1-1 §6.6.4, §6.6.6.4)');
input('Slab: 0 = solid slab, 1 = composite slab on profiled steel deck', 'c_{deck}', 0);
input('Deck ribs: 0 = transverse to the beam, 1 = parallel to the beam', 'c_{par}', 0);
T('Default deck: RF55 (Fielders KingFlor; M Metal, Singapore), 1.00 mm BMT, re-entrant, ribs at 200 mm:');
T('h_p 55 mm, 1664 mm²/m, 13.56 kg/m², G550 (manufacturer data sheet).');
T('b_r = 168 mm assumes a 32 mm dovetail; confirm with the supplier (k_t is at its Table 6.2 limit either way).');
input('Profile: 0 = open trapezoidal, 1 = re-entrant (dovetail)', 'c_{re}', 1);
input('Deck depth, overall, without embossments', 'h_p', 55, 'mm');
input('Concrete rib width b_0 of EC4 Figure 6.13 (mean width of an open rib; minimum width if re-entrant)', 'b_r', 168, 'mm');
input('Rib pitch', 'e_r', 200, 'mm');
input('Sheet thickness', 't_p', 1, 'mm');
input('Studs per rib, ribs transverse (1 or 2)', 'n_r', 1);
input('Deck self-weight', 'g_p', 0.133, 'kPa');
input('Transverse deck fixed to the top flange restrains the beam in construction: 1 = yes, 0 = no', 'c_{LT.d}', 1);
input('Transverse deck continuous across the beam, counted as transverse reinforcement (6.25): 1 = yes, 0 = no', 'c_{pe}', 0);
input('Sheet cross-section per metre of beam (manufacturer)', 'A_{pe}', 1664, 'mm^2/m');
input('Deck yield strength', 'f_{yp}', 550, 'MPa');
input('Transverse bar layers in a deck slab: 1 = one layer on the deck, below the stud heads (A_b only); 2 = top and bottom', 'n_{lay}', 1);

H(2, '2. LOADING');
l.out[l.out.length - 1].props.pageBreak = true; // loading starts on its own page
H(3, '2.1 Construction stage (steel beam alone)');
T('Deck in effect (1.11): solid slab h_pe = 0; deck: h_pe = h_p, concrete above the deck h_t = h_c − h_p.');
P('Deck depth in effect', R`h_{pe}\coloneq${IF([R`c_{deck}\ge1`, 'h_p'], [null, R`0\,\mathrm{mm}`])}`, M(units('mm')));
calc('Concrete above the deck (whole slab if solid)', 'h_t', R`h_c-h_{pe}`, 'mm', false);
P('Deck ribs transverse to the beam: 1 = yes, 0 = no (solid or parallel)', R`c_{tr}\coloneq${IF([R`c_{deck}\ge1\land c_{par}<1`, '1'], [null, '0'])}`, M({ precision: 0 }));
P('Deck self-weight on the beam', R`g_d\coloneq${IF([R`c_{deck}\ge1`, R`g_p s_b`], [null, R`0\,\mathrm{kN/m}`])}`, M(units('kN/m')));
T('Self weight of the steel g_a, wet slab g_c (concrete in the ribs and the deck included) and their sum g_0 (carried in every stage):');
calc('Steel beam', 'g_a', R`m_a\cdot9.81\,\mathrm{m/s^2}`, 'kN/m', false);
P('Concrete share of the rib zone: b_r / e_r for an open profile; 1 for a re-entrant one (dovetail voids ignored, on the heavy side)', R`k_c\coloneq${IF([R`c_{re}\ge1`, '1'], [null, R`\frac{b_r}{e_r}`])}`, M({ precision: 3 }));
calc('Wet slab: topping, share k_c of the rib zone, deck', 'g_c', R`\rho_c s_b\left(h_c-h_{pe}\left(1-k_c\right)\right)+g_d`, 'kN/m', false);
calc('Self-weight', 'g_0', R`g_a+g_c`, 'kN/m', false);
P('ULS factor on self-weight g_0, fixed (EN 1990 Table A1.2(B), not a user input)', R`\gamma_{G.sw}\coloneq1.35`, M(units('')));
P('Construction span (ends or props)', R`L_1\coloneq${IF([R`c_{prop}\ge1`, R`k_{LT}L`], [null, 'L'])}`, M(units('m')));
calc('ULS construction load', 'w_{1.Ed}', R`\gamma_{G.sw}g_0+\gamma_G g_{form}s_b+\gamma_Q q_{con}s_b`, 'kN/m', false);
calc('Construction shear', 'V_{1.Ed}', R`\frac{w_{1.Ed}L_1}{2}`, 'kN', false);
calc('Construction moment', 'M_{1.Ed}', R`\frac{w_{1.Ed}L_1^2}{8}`, 'kN m', false);
H(3, '2.2 Permanent (composite) stage: g0 plus the load tables');
fig('F1', 'Composite-stage loading (rows of the load tables)', 'loads', 4);
LINK('forces', 'Internal forces along the span from the load tables', () => {
 calc('Diagram step (200 intervals)', '\\Delta x', R`\frac{L}{200}`, 'mm', false);
 T('Table columns as vectors (row 0 first). Simply supported beam, x from support A.');
 for (const [n, t] of [['x_{u1}','x_{1.i}'],['x_{u2}','x_{2.i}'],['c_u','c_{Q.i}'],['p_u','p_{k.i}'],['a_P','a_{j}'],['c_P','c_{Q.j}'],['F_P','F_{k.j}'],['\\gamma_u','\\gamma_{F.i}'],['\\gamma_P','\\gamma_{F.j}']])
  calc(`Table column ${t} as a vector${t.startsWith('c_') ? ' (G → 0, Q → 1)' : ''}`, n, R`\mathrm{col}\left(${t},0\right)`, '', false);
 calc('Permanent line loads, p_k × s_b on G rows', 'g_u', R`s_b\overrightarrow{p_u\left(1-c_u\right)}`, 'kN/m', false);
 calc('Imposed line loads, p_k × s_b on Q rows', 'q_u', R`s_b\overrightarrow{p_u c_u}`, 'kN/m', false);
 calc('Permanent point loads (G rows)', 'G_P', R`\overrightarrow{F_P\left(1-c_P\right)}`, 'kN', false);
 calc('Imposed point loads (Q rows)', 'Q_P', R`\overrightarrow{F_P c_P}`, 'kN', false);
 calc('Design line loads per row, γ_F p_k s_b (ULS)', 'w_U', R`s_b\overrightarrow{\gamma_u p_u}`, 'kN/m', false);
 calc('Design point loads per row, γ_F F_k (ULS)', 'F_U', R`\overrightarrow{\gamma_P F_P}`, 'kN', false);
 calc('Loaded lengths', 'l_u', R`x_{u2}-x_{u1}`, 'm', false);
 calc('Reaction at A per unit distributed load', 'r_u', R`\frac{l_u\left(L-\frac{x_{u1}+x_{u2}}{2}\right)}{L}`, 'm', false);
 P('Left-part moment per unit row load', R`m_u(x)\coloneq${IF([R`x\le x_{u1}`, R`0\,\mathrm{m^2}`], [R`x\ge x_{u2}`, R`l_u\left(x-\frac{x_{u1}+x_{u2}}{2}\right)`], [null, R`\frac{\left(x-x_{u1}\right)^2}{2}`])}`, M(units('')));
 P('Row load left of x per unit load', R`v_u(x)\coloneq${IF([R`x\le x_{u1}`, R`0\,\mathrm{m}`], [R`x\ge x_{u2}`, R`l_u`], [null, R`x-x_{u1}`])}`, M(units('')));
 P('Lever of each point load to the right of x', R`m_P(x)\coloneq${IF([R`x>a_P`, R`x-a_P`], [null, R`0\,\mathrm{m}`])}`, M(units('')));
 P('Point loads left of x (1) or not (0)', R`h_P(x)\coloneq${IF([R`x>a_P`, '1'], [null, '0'])}`, M(units('')));
 P('Moment per unit row load', R`k_u(x)\coloneq r_u x-m_u(x)`, M(units('')));
 P('Moment at x per unit point load', R`k_P(x)\coloneq\frac{L-a_P}{L}x-m_P(x)`, M(units('')));
 P('Moment from the tables with factors cG on g, G and cQ on q, Q', R`M_s(x,c_G,c_Q)\coloneq\mathrm{dot}\left(c_G g_u+c_Q q_u,k_u(x)\right)+\mathrm{dot}\left(c_G G_P+c_Q Q_P,k_P(x)\right)`, M(units('')));
 P('Shear from the tables with the same factors', R`V_s(x,c_G,c_Q)\coloneq\mathrm{dot}\left(c_G g_u+c_Q q_u,r_u-v_u(x)\right)+\mathrm{dot}\left(c_G G_P+c_Q Q_P,\frac{L-a_P}{L}-h_P(x)\right)`, M(units('')));
 P('ULS moment from the tables, each row with its own γ_F', R`M_U(x)\coloneq\mathrm{dot}\left(w_U,k_u(x)\right)+\mathrm{dot}\left(F_U,k_P(x)\right)`, M(units('')));
 P('ULS shear from the tables, each row with its own γ_F', R`V_U(x)\coloneq\mathrm{dot}\left(w_U,r_u-v_u(x)\right)+\mathrm{dot}\left(F_U,\frac{L-a_P}{L}-h_P(x)\right)`, M(units('')));
 calc('Points along the span, 200 intervals', 'x_v', R`\mathrm{seq}\left(0\,\mathrm{m},L,\Delta x\right)`, 'm', 'fo');
 T('Table-load moments and shears along the span (independent of the steel section, so calculated once):');
 calc('ULS moment of the table loads', 'M_{U.v}', R`\mathrm{map}\left(M_U,x_v\right)`, 'kN m', 'fo');
 calc('ULS shear of the table loads', 'V_{U.v}', R`\mathrm{map}\left(V_U,x_v\right)`, 'kN', 'fo');
 calc('ULS moment of the table loads under each point load', 'M_{U.P}', R`\mathrm{map}\left(M_U,a_P\right)`, 'kN m', false);
 calc('Characteristic moment, G + ψ_2 Q (quasi-permanent)', 'M_{s.qp}', R`\mathrm{map}\left(M_s,x_v,1,\psi_2\right)`, 'kN m', 'fo');
 calc('Characteristic moment, (1 − ψ_2) Q (transient)', 'M_{s.tr}', R`\mathrm{map}\left(M_s,x_v,0,1-\psi_2\right)`, 'kN m', 'fo');
 calc('Characteristic moment, G + Q', 'M_{s.k}', R`\mathrm{map}\left(M_s,x_v,1,1\right)`, 'kN m', 'fo');
 calc('Characteristic moment, ψ_2 Q', 'M_{q.qp}', R`\mathrm{map}\left(M_s,x_v,0,\psi_2\right)`, 'kN m', 'fo');
 calc('Characteristic moment, Q', 'M_{q.k}', R`\mathrm{map}\left(M_s,x_v,0,1\right)`, 'kN m', 'fo');
 calc('Design bending moment along the span', 'M_v', R`\gamma_{G.sw}g_0\frac{x_v\left(L-x_v\right)}{2}+M_{U.v}`, 'kN m', 'fo');
 calc('Design shear force along the span', 'V_v', R`\gamma_{G.sw}g_0\left(\frac{L}{2}-x_v\right)+V_{U.v}`, 'kN', 'fo');
 calc('Design moments under the point loads', 'M_P', R`\gamma_{G.sw}g_0\frac{a_P\left(L-a_P\right)}{2}+M_{U.P}`, 'kN m', false);
 calc('Maximum design moment', 'M_{2.Ed}', R`\max\left(\max\left(M_v\right),\max\left(M_P\right)\right)`, 'kN m', false);
 calc('Position of the maximum moment', 'x_M', R`\mathrm{at}\left(x_v,\mathrm{at}\left(\mathrm{match}\left(\max\left(M_v\right),M_v\right),0\right)\right)`, 'm', false);
 calc('Maximum design shear (support)', 'V_{2.Ed}', R`\max\left(\mathrm{at}\left(V_v,0\right),-\mathrm{at}\left(V_v,\mathrm{last}\left(V_v\right)\right)\right)`, 'kN', false);
});
T('Maximum design moment M_2,Ed at x_M and support shear V_2,Ed (calculated in annex A.1):');
l.ROW([[96, R`M_{2.Ed}=`, units('kN m')], [316, R`x_M=`, units('m')], [496, R`V_{2.Ed}=`, units('kN')]], 1);
DIAGRAM(135, { title: 'Shear force diagram V_Ed', xUnit: 'm', yUnit: 'kN', series: [S('v', '', ['x_v', 'V_v'], 'area', '#1d4ed8', 1.5), S('vv', '', [R`\mathrm{stack}\left(0\,\mathrm{m},L\right)`, R`\mathrm{stack}\left(\mathrm{at}\left(V_v,0\right),\mathrm{at}\left(V_v,\mathrm{last}\left(V_v\right)\right)\right)`], 'values', '#1d4ed8', 1.5)] });
DIAGRAM(135, { title: 'Bending moment diagram M_Ed (sagging drawn below, tension side)', xUnit: 'm', yUnit: 'kN m', invertY: true, series: [S('m', '', ['x_v', 'M_v'], 'area', '#b91c1c', 1.5), S('mv', '', ['x_M', 'M_{2.Ed}'], 'values', '#b91c1c', 1.5), S('mp', '', ['a_P', 'M_P'], 'values', '#7f1d1d', 1.5)] });


H(2, '3. EN 1993-1-1 — STEEL BEAM, CONSTRUCTION STAGE');
l.out[l.out.length - 1].props.pageBreak = true;
calc('Steel design strength', 'f_{yd}', R`\frac{f_y}{\gamma_{M0}}`, 'MPa', false);
H(3, '3.1 Classification (Table 5.2)');
calc('Material parameter', '\\varepsilon', R`\sqrt{\frac{235\,\mathrm{MPa}}{f_y}}`, '', false);
calc('Flange outstand c/(t ε)', '\\beta_f', R`\frac{b_a-t_w-2r}{2t_f\varepsilon}`, '', false);
check('Class 1 flange', '\\beta_f','9');
calc('Web in bending c/(t ε)', '\\beta_w', R`\frac{h_a-2t_f-2r}{t_w\varepsilon}`, '', false);
check('Class 1 web', '\\beta_w', '72');
H(3, '3.2 Resistance (§6.2.5, §6.2.6, §6.2.8)');
calc('Shear area, η = 1.0 (conservative)', 'A_v', R`A_a-2b_a t_f+\left(t_w+2r\right)t_f`, 'mm^2', false);
calc('Plastic bending resistance', 'M_{a.Rd}', R`W_{pl}f_{yd}`, 'kN m', false);
calc('Plastic shear resistance', 'V_{pl.Rd}', R`\frac{A_v f_{yd}}{\sqrt{3}}`, 'kN', false);
ur('Construction bending', 'M.1','M_{1.Ed}','M_{a.Rd}');
ur('Construction shear','V.1','V_{1.Ed}','V_{pl.Rd}');
check('Low shear: no M-V reduction', 'V_{1.Ed}', '0.5V_{pl.Rd}');
H(3, '3.3 Lateral-torsional buckling (§6.3.2.2; Mcr from SCI SN003b)');
T('No restraint credit from wet slab or formwork. Unpropped: fork ends over L; propped: L_LT = k_LT L.');
T('Deck transverse and fixed to the top flange at every rib (c_LT.d = 1; SCI P300 practice): the flange is restrained at the rib pitch, L_LT = e_r. Deck parallel: no restraint.');
