calc('Shear stress on c-c','v_{c.Ed}',R`\frac{v_f}{l_c}`,'MPa', false);
calc('Strut angle on c-c, cot θ_f','c_{\\theta.c}',R`c_\theta\left(v_{c.Ed}\right)`,'', false);
calc('Strut resistance on c-c, (6.22)','v_{c.Rd}',R`\frac{v_{max}}{c_{\theta.c}+1/c_{\theta.c}}`,'MPa', false);
calc('Required steel, (6.21) with h_f = l_c','a_{sf.c.req}',R`\frac{v_{c.Ed} l_c}{f_{sd}c_{\theta.c}}`,'mm^2/m', false);
ur('Transverse reinforcement, c-c (0 if not required)','sf.c','c_{cc}a_{sf.c.req}','a_{sf.b}');
ur('Concrete strut, c-c (0 if not required)','L.c','c_{cc}v_{c.Ed}','v_{c.Rd}');
T('Deck: bottom bars A_b lie on the deck, at least 30 mm below the stud head (§6.6.5.1). Not checked: discontinuous deck anchored by the studs (6.26), surface d-d and haunches, splitting at edge beams (§6.6.5.3), anchorage lengths, minimum reinforcement (EC2 §9.2.2(5)), transverse slab bending.');

H(2, '6. NON-COMPOSITE ALTERNATIVE (EN 1993-1-1, EN 1993-1-5)');
l.out[l.out.length - 1].props.pageBreak = true;
T('Used only if composite action fails: η < η_min, too few studs, or M_Rd(x) < M_Ed(x) (chapter 4).');
P('Composite action: 1 = yes (ch. 4), 0 = no (ch. 6)', R`c_{comp}=`, M({ precision: 0 }));
T('Bare steel beam for all permanent-stage loads, no composite credit. Studs at s ≤ s_max restrain the');
T('top flange (EN 1994-1-1 §6.4.1(1)), so L_LT = stud spacing. Deflection on the steel section alone.');
LINK('noncomp', 'Non-composite alternative: steel section alone', () => {
 T('Bending, shear and M–V interaction, steel section alone (§6.2.5, §6.2.6, §6.2.8)');
 calc('Bending, steel alone, at x_M', R`\mathrm{UR}_{M.nc}`, R`\frac{M_{2.Ed}}{M_{a.Rd}}`);
 calc('Shear, steel web', R`\mathrm{UR}_{V.nc}`, R`\frac{V_{2.Ed}}{V_{pl.Rd}}`);
 calc('Web area', 'A_w', R`h_w t_w`, 'mm^2', false);
 calc('(6.30) along the span, ρ from 4.6', 'M_{V.nc.x}', R`\left(W_{pl}-\frac{A_w^2}{4t_w}\rho_v\right)f_{yd}`, 'kN m', 'fo');
 calc('(6.30) under each point load', 'M_{V.nc.P}', R`\left(W_{pl}-\frac{A_w^2}{4t_w}\rho_P\right)f_{yd}`, 'kN m', 'fo');
 calc('Bending with shear', R`\mathrm{UR}_{MV.nc}`, R`\max\left(\max\left(\overrightarrow{\frac{M_v}{M_{V.nc.x}}}\right),\max\left(\overrightarrow{\frac{M_P}{M_{V.nc.P}}}\right)\right)`, '', false);
 T('Lateral-torsional buckling (EN 1994-1-1 §6.4.1(1); EN 1993-1-1 §6.3.2.2)');
 T('EN 1994-1-1 §6.4.1(1): a steel flange attached to the slab by shear connection to §6.6 may be');
 T('taken as laterally stable if the slab is laterally stable. Applied when s ≤ s_max (§6.6.5.5);');
 T('L_LT is then the stud spacing (χ_LT = 1). Otherwise the full span is used as unrestrained.');
 P('Top flange restrained by the studs (1) or not (0)', R`c_{rest}\coloneq${IF([R`s_A\le s_{max}\land s_B\le s_{max}`, '1'], [null, '0'])}`, M({ precision: 0 }));
 P('LTB length', R`L_{LT.nc}\coloneq${IF([R`c_{rest}\ge1`, R`\max\left(s_A,s_B\right)`], [null, 'L'])}`, M(units('mm')));
 calc('Euler force (C1 = 1, z_g = 0)', 'N_{cr.nc}', R`\frac{\pi^2 E_a I_z}{L_{LT.nc}^2}`, 'kN', false);
 calc('Elastic critical moment', 'M_{cr.nc}', R`N_{cr.nc}\sqrt{\frac{I_w}{I_z}+\frac{G_a I_t}{N_{cr.nc}}}`, 'kN m', false);
 calc('Slenderness', '\\lambda_{LT.nc}', R`\sqrt{\frac{W_{pl}f_y}{M_{cr.nc}}}`, '', false);
 calc('(6.56)', '\\Phi_{LT.nc}', R`0.5\left(1+\alpha_{LT}\left(\lambda_{LT.nc}-0.2\right)+\lambda_{LT.nc}^2\right)`, '', false);
 calc('Reduction factor', '\\chi_{LT.nc}', R`\min\left(1,\frac{1}{\Phi_{LT.nc}+\sqrt{\Phi_{LT.nc}^2-\lambda_{LT.nc}^2}}\right)`, '', false);
 calc('(6.55)', 'M_{b.Rd.nc}', R`\frac{\chi_{LT.nc}W_{pl}f_y}{\gamma_{M1}}`, 'kN m', false);
 calc('LTB', R`\mathrm{UR}_{LT.nc}`, R`\frac{M_{2.Ed}}{M_{b.Rd.nc}}`);
 T('Web under point loads, steel alone (EN 1993-1-5 §6, §7.2)');
 T('η2 as in 4.7 (same web). η1 = M_Ed / M_el,Rd of the steel section, (4.14) with gross W_el.');
 calc('Elastic moment resistance, steel', 'M_{el.Rd}', R`\frac{2I_a}{h_a}f_{yd}`, 'kN m', false);
 calc('(7.2) as a utilisation', R`\mathrm{UR}_{FM.nc}`, R`c_{F.P}\max\left(\overrightarrow{\frac{\frac{F_{loc}}{F_{Rd.a}}+0.8\frac{M_P}{M_{el.Rd}}}{1.4}}\right)`, '', false);
 T('Deflection, steel section alone (characteristic loads)');
 calc('g0 and the load tables on the steel alone, maximum along the span (4.9), less the precamber', '\\delta_{nc}', R`\max\left(\delta_{x.s}-w_{c.v}\right)`, 'mm', false);
 calc('Deflection, steel alone', R`\mathrm{UR}_{d.nc}`, R`\frac{\delta_{nc}}{\delta_{lim}}`);
 calc('Live-load deflection, steel alone', R`\mathrm{UR}_{d.q.nc}`, R`\frac{\max\left(\delta_{x.qs}\right)}{\delta_{lim.q}}`);
 T('Natural frequency, steel section alone (same mass loads as 4.10)');
 calc('Midspan deflection under the mass loads, steel alone', '\\delta_{dyn.nc}', R`\frac{\Delta x\,\mathrm{sum}\left(M_{dyn.v}m_v\right)}{E_a I_a}`, 'mm', false);
 calc('Natural frequency, steel alone', 'f_{1.nc}', R`\frac{18\,\mathrm{Hz}}{\sqrt{\frac{\delta_{dyn.nc}}{1\,\mathrm{mm}}}}`, 'Hz', false);
 calc('Natural frequency', R`\mathrm{UR}_{fn.nc}`, R`\frac{f_{lim}}{f_{1.nc}}`);
});
T('Key results (calculated in the annex):');
l.ROW([[96, R`L_{LT.nc}=`, units('mm')], [316, R`\chi_{LT.nc}=`, M({ precision: 3 })], [496, R`\delta_{nc}=`, units('mm')]], 1);
for (const n of ['MV.nc','LT.nc','FM.nc','d.nc','d.q.nc']) P(`Utilisation ${n}`, R`\mathrm{UR}_{${n}}=`, M({ precision: 3 }));

H(2, '7. SUMMARY BY CODE');
H(3, 'Design basis — composite (chapter 4) or non-composite (chapter 6)');
P('Composite action achieved (1 = yes, 0 = no)', R`c_{comp}=`, M({ precision: 0 }));
const WHEN = (cond, ...lines) => { for (const t of lines) { T(t); Object.assign(l.out[l.out.length - 1].props, { showWhen: cond, color: '#b91c1c' }); } };
const WHEN_OK = (cond, ...lines) => { for (const t of lines) { T(t); l.out[l.out.length - 1].props.showWhen = cond; } };
WHEN_OK(R`c_{comp}\ge1`, 'Design basis: COMPOSITE (chapter 4). Chapter 6 is for information only.');
WHEN(R`c_{comp}<1`, 'NOT DESIGNED AS COMPOSITE: designed as a bare steel beam (chapter 6); see the note below.');
P('Web checks, both bases (4.7)', R`\mathrm{UR}_{F}\coloneq\max\left(\mathrm{UR}_{F.P},\mathrm{UR}_{F.S}\right)`, M({ precision: 3 }));
P('Slab longitudinal shear, a-a, b-b and c-c (chapter 5)', R`\mathrm{UR}_{slab}\coloneq\max\left(\mathrm{UR}_{sf},\mathrm{UR}_{L},\mathrm{UR}_{sf.b},\mathrm{UR}_{L.b},\mathrm{UR}_{sf.c},\mathrm{UR}_{L.c}\right)`, M({ precision: 3 }));
P('Serviceability, composite: deflection, live-load deflection, frequency', R`\mathrm{UR}_{sls}\coloneq\max\left(\mathrm{UR}_{d.x},\mathrm{UR}_{d.q},\mathrm{UR}_{fn}\right)`, M({ precision: 3 }));
P('Serviceability, bare steel', R`\mathrm{UR}_{sls.nc}\coloneq\max\left(\mathrm{UR}_{d.nc},\mathrm{UR}_{d.q.nc},\mathrm{UR}_{fn.nc}\right)`, M({ precision: 3 }));
P('Governing utilisation, composite (chapters 4 and 5)', R`\mathrm{UR}_{c}\coloneq\max\left(\mathrm{UR}_{M.2},\mathrm{UR}_{M.x},\mathrm{UR}_{MV},\mathrm{UR}_{V.2},\mathrm{UR}_{F},\mathrm{UR}_{FM},\mathrm{UR}_{sls},\mathrm{UR}_{slab}\right)`, M({ precision: 3 }));
P('Governing utilisation, non-composite (chapter 6)', R`\mathrm{UR}_{nc}\coloneq\max\left(\mathrm{UR}_{M.nc},\mathrm{UR}_{MV.nc},\mathrm{UR}_{V.nc},\mathrm{UR}_{LT.nc},\mathrm{UR}_{F},\mathrm{UR}_{FM.nc},\mathrm{UR}_{sls.nc}\right)`, M({ precision: 3 }));
P('Governing utilisation of the design basis used', R`\mathrm{UR}_{des}\coloneq${IF([R`c_{comp}\ge1`, R`\mathrm{UR}_{c}`], [null, R`\mathrm{UR}_{nc}`])}`, M({ precision: 3 }));
check('Acceptance, permanent stage', '\\mathrm{UR}_{des}', '1');

H(3, 'EN 1993-1-1 — construction stage');
for (const n of ['M.1','V.1','LT','d.1']) P(`Utilisation ${n}`,R`\mathrm{UR}_{${n}}=`,M({precision:3}));
H(3, 'EN 1994-1-1 — composite beam');
for (const n of ['M.2','M.x','MV','V.2','F.P','F.S','FM','d.2','d.x','d.q']) P(`Utilisation ${n}`,R`\mathrm{UR}_{${n}}=`,M({precision:3}));
H(3, 'EN 1994-1-1 §6.6.6 / EN 1992-1-1 — slab longitudinal shear (a-a, b-b)');
for (const n of ['sf','L','sf.b','L.b','sf.c','L.c']) P(`Utilisation ${n}`,R`\mathrm{UR}_{${n}}=`,M({precision:3}));

WHEN(R`c_{comp}<1`,
  'NOT DESIGNED AS COMPOSITE: the studs that fit cannot give composite action (η < η_min,',
  'too few studs, or M_Rd(x) < M_Ed(x), e.g. a large point load close to a support).',
  'Designed as a BARE STEEL beam (chapter 6, annex): EN 1993-1-1 and EN 1993-1-5 met by the steel',
  'alone; LTB length = stud spacing (top flange restrained, s ≤ s_max, EN 1994-1-1 §6.4.1(1), §6.6.5.5);',
  'UR uses the steel-alone deflection, not the composite one. If it fails, enlarge the section (Browse).');
T('REVIEW DRAFT. If UR_LT > 1, the bare beam needs temporary restraint or propping during construction.');
T('Gates: Singapore NAs; shrinkage history and cracking; surfaces c-c/d-d, splitting and anchorage lengths.');
LINK('sources','References and SCI cross-check', () => {
 T('SCI P364 (2009/10) Example 8, 533×165×75 S275, L = 12 m, C25/30 — same equations, checked:');
 T('  P_c,Rd 73.7 kN (6.19 governs), η_min 0.50, x_c 61.5 mm, M_pl,Rd 952.4 kNm, M_Rd 715.7 kNm (6.3).');
 T('  Rigid-plastic, PNA in flange: x_pl = (N_pl,a − N_c)/(2 f_y b) as here; SCI 903.9 vs 912 kNm here');
 T('  (+0.9 %); the printed SCI expression is not legible in the extract (deck slab in SCI).');
 T('SBE Part 4 (2009) example A.4, IPE 400 S355, L = 9 m, two point loads — inputs replaced, checked:');
 T('  M_Ed 465.6 kNm, V_Ed 156.2 kN, M_a,Rd 464.0 kNm, V_pl,Rd 875.0 kN, η_min 0.52, b_eff 2.25 m — match;');
 T('  N_c = 1403 kN: PNA 12.5 mm below steel top (SBE 12); M_Rd 755 vs 738 kNm (deck, +2.3 %).');
 T('Solid slab, HK notes: UB 457×152×52 S355, L 12 m, h_c 125 mm, C30/37 — inputs replaced:');
 T('  b_eff 2.8 m, N_a 2364 kN, PNA in slab, lever 325.1 mm, M_pl,Rd 768.6 vs 768.5 kNm — match.');
 T('SCI P359 (2011) §4.2.3: N_c = η N_c,f; linear interaction conservative; η_min §4.4.3.');
 T('SCI P405 (2015) §4.2.1: studs counted from the support to the maximum moment.');
 T('SCI NCCI SN003b: M_cr and C1, C2 for UDL, fork ends, top-flange load.');
 T('EC4 §§2.4.1.2, 5.4.1.2, 5.4.2.2, 6.2.1, 6.2.2, 6.6.1–6.6.6, 7.3.1; EC3 §§5.5, 6.2, 6.3.2.2; EC2 §6.2.4.');
 T('Slip factors 0.3 / 0.5 follow SCI guidance (PN002a, ENV 1994-1-1); not an SS EN NA rule.');
});
finish({ id:'tpl-composite-beam-ec4', title:'Composite Beam EC4 — Review Draft', reference:'CALC-EC4-01', file:'Composite_Beam_EC4.mCCV' });
